pub fn snapshot_identity_step(composition: Rc<SourceComposition>, acc: Rc<SnapshotIdentityAcc>, file: Rc<SnapshotSourceFile>) -> Rc<SnapshotIdentityAcc> {
    match acc.refusal.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => {
        let path = snapshot_source_file_path(file.clone());
match (*admit_relative_source_path(path.clone())).clone() {
    RelativePathAdmission::RelativePathRefused { text: t, cause: c, .. } => Rc::new(SnapshotIdentityAcc {
    entries: acc.entries.clone(),
    last: acc.last.clone(),
    refusal: Some(Rc::new(SnapshotIdentityRefusal::SnapshotIdentityPathRefused {
    cause: Rc::new(SnapshotCaptureRefusal::SnapshotPathNotRelative {
    path: t.clone(),
    cause: c.clone(),
}),
})),
}),
    RelativePathAdmission::RelativePathAdmitted { path: relative, .. } => if !snapshot_path_inside_composition(composition.clone(), relative.clone()) {
            Rc::new(SnapshotIdentityAcc {
    entries: acc.entries.clone(),
    last: acc.last.clone(),
    refusal: Some(Rc::new(SnapshotIdentityRefusal::SnapshotIdentityPathRefused {
    cause: Rc::new(SnapshotCaptureRefusal::SnapshotPathOutsideComposition {
    path: path.clone(),
    composition: source_composition_wire(composition.clone()),
}),
})),
})
        } else {
            if (acc.last.clone().as_deref() == Some(path.clone()).as_deref()) {
                Rc::new(SnapshotIdentityAcc {
    entries: acc.entries.clone(),
    last: acc.last.clone(),
    refusal: Some(Rc::new(SnapshotIdentityRefusal::SnapshotIdentityDuplicatePath {
    path: path.clone(),
})),
})
            } else {
                Rc::new(SnapshotIdentityAcc {
    entries: v1_rt::concat(acc.entries.clone(), Rc::new(vec![snapshot_identity_entry_ref(file.clone())])),
    last: Some(path.clone()),
    refusal: std::option::Option::None,
})
            }
        },
}
},
}
}

pub fn snapshot_manifest_identity(composition: Rc<SourceComposition>, files: Rc<Vec<Rc<SnapshotSourceFile>>>) -> Rc<SnapshotIdentity> {
    match (*Rc::new({ let mut __keyed: Vec<_> = files.iter().cloned().map(|__e: Rc<SnapshotSourceFile>| { let __k = (|f: Rc<SnapshotSourceFile>| snapshot_source_file_path(f.clone()))(__e.clone()); (__k, __e) }).collect(); __keyed.sort_by(|__x, __y| v1_rt::canonical_key_cmp(&__x.0, &__y.0)); __keyed.into_iter().map(|(_, __e)| __e).collect::<Vec<_>>() }).iter().cloned().fold(Rc::new(SnapshotIdentityAcc {
    entries: Rc::new(vec![]),
    last: std::option::Option::None,
    refusal: std::option::Option::None,
}), |acc: Rc<SnapshotIdentityAcc>, file: Rc<SnapshotSourceFile>| snapshot_identity_step(composition.clone(), acc, file.clone()))).clone() {
    SnapshotIdentityAcc { entries, refusal, .. } => match refusal.clone() {
    Some(cause) => Rc::new(SnapshotIdentity::SnapshotIdentityRefused {
    cause: cause.clone(),
}),
    std::option::Option::None => Rc::new(SnapshotIdentity::SnapshotIdentified {
    manifest: crate::std_fabric_storage::fabric_object_ref_of(snapshot_manifest_object(entries.clone(), composition.clone())),
    files: (entries.clone().len() as i64),
    composition: source_composition_wire(composition.clone()),
}),
},
}
}

